                return;
            }

            Modal.createDialog(ErrorDialog, {
                title: _t('Call Failed'),
                description: err.message,
            });
        });
        call.on(CallEvent.Hangup, () => {
            if (!this.matchesCallForThisRoom(call)) return;

            this.removeCallForRoom(mappedRoomId);
        });
        call.on(CallEvent.State, (newState: CallState, oldState: CallState) => {
            this.onCallStateChanged(newState, oldState, call);
        });
        call.on(CallEvent.Replaced, (newCall: MatrixCall) => {
            if (!this.matchesCallForThisRoom(call)) return;

            logger.log(`Call ID ${call.callId} is being replaced by call ID ${newCall.callId}`);

            if (call.state === CallState.Ringing) {
                this.pause(AudioID.Ring);
            } else if (call.state === CallState.InviteSent) {
                this.pause(AudioID.Ringback);
            }

            this.removeCallForRoom(mappedRoomId);
            this.addCallForRoom(mappedRoomId, newCall);
            this.setCallListeners(newCall);
            this.setCallState(newCall, newCall.state);
        });
        call.on(CallEvent.AssertedIdentityChanged, async () => {
            if (!this.matchesCallForThisRoom(call)) return;

            logger.log(`Call ID ${call.callId} got new asserted identity:`, call.getRemoteAssertedIdentity());

            if (!this.shouldObeyAssertedfIdentity()) {
                logger.log("asserted identity not enabled in config: ignoring");
                return;
            }

            const newAssertedIdentity = call.getRemoteAssertedIdentity().id;
            let newNativeAssertedIdentity = newAssertedIdentity;
            if (newAssertedIdentity) {
                const response = await this.sipNativeLookup(newAssertedIdentity);
                if (response.length && response[0].fields.lookup_success) {
                    newNativeAssertedIdentity = response[0].userid;
                }
            }
            logger.log(`Asserted identity ${newAssertedIdentity} mapped to ${newNativeAssertedIdentity}`);

            if (newNativeAssertedIdentity) {
                this.assertedIdentityNativeUsers[call.callId] = newNativeAssertedIdentity;

                // If we don't already have a room with this user, make one. This will be slightly odd
                // if they called us because we'll be inviting them, but there's not much we can do about
                // this if we want the actual, native room to exist (which we do). This is why it's
                // important to only obey asserted identity in trusted environments, since anyone you're
                // on a call with can cause you to send a room invite to someone.
                await ensureDMExists(MatrixClientPeg.get(), newNativeAssertedIdentity);

                const newMappedRoomId = this.roomIdForCall(call);
                logger.log(`Old room ID: ${mappedRoomId}, new room ID: ${newMappedRoomId}`);
                if (newMappedRoomId !== mappedRoomId) {
                    this.removeCallForRoom(mappedRoomId);
                    mappedRoomId = newMappedRoomId;
                    logger.log("Moving call to room " + mappedRoomId);
                    this.addCallForRoom(mappedRoomId, call, true);
                }
            }
        });
    }

    private onCallStateChanged = (newState: CallState, oldState: CallState, call: MatrixCall): void => {
        if (!this.matchesCallForThisRoom(call)) return;

        const mappedRoomId = this.roomIdForCall(call);
        this.setCallState(call, newState);
        dis.dispatch({
            action: 'call_state',
            room_id: mappedRoomId,
            state: newState,
        });

        switch (oldState) {
            case CallState.Ringing:
                this.pause(AudioID.Ring);
                break;
            case CallState.InviteSent:
                this.pause(AudioID.Ringback);
                break;
        }

        if (newState !== CallState.Ringing) {
            this.silencedCalls.delete(call.callId);
        }

        switch (newState) {
            case CallState.Ringing: {
                const incomingCallPushRule = (
                    new PushProcessor(MatrixClientPeg.get()).getPushRuleById(RuleId.IncomingCall)
                );
                const pushRuleEnabled = incomingCallPushRule?.enabled;
                const tweakSetToRing = incomingCallPushRule?.actions.some((action: Tweaks) => (
                    action.set_tweak === TweakName.Sound &&
                    action.value === "ring"
                ));

                if (pushRuleEnabled && tweakSetToRing && !this.isForcedSilent()) {
                    this.play(AudioID.Ring);
                } else {
                    this.silenceCall(call.callId);
                }
                break;
            }
            case CallState.InviteSent: {
                this.play(AudioID.Ringback);
                break;
            }
            case CallState.Ended: {
                const hangupReason = call.hangupReason;
                this.removeCallForRoom(mappedRoomId);
                if (oldState === CallState.InviteSent && call.hangupParty === CallParty.Remote) {
                    this.play(AudioID.Busy);

                    // Don't show a modal when we got rejected/the call was hung up
                    if (!hangupReason || [CallErrorCode.UserHangup, "user hangup"].includes(hangupReason)) break;

                    let title;
                    let description;
                    // TODO: We should either do away with these or figure out a copy for each code (expect user_hangup...)
                    if (call.hangupReason === CallErrorCode.UserBusy) {
                        title = _t("User Busy");
                        description = _t("The user you called is busy.");
                    } else {
                        title = _t("Call Failed");
                        description = _t("The call could not be established");
                    }

                    Modal.createDialog(ErrorDialog, {
                        title, description,
                    });
                } else if (
                    hangupReason === CallErrorCode.AnsweredElsewhere && oldState === CallState.Connecting
                ) {
                    Modal.createDialog(ErrorDialog, {
                        title: _t("Answered Elsewhere"),
                        description: _t("The call was answered on another device."),
                    });
                } else if (oldState !== CallState.Fledgling && oldState !== CallState.Ringing) {
                    // don't play the end-call sound for calls that never got off the ground
                    this.play(AudioID.CallEnd);
                }

                this.logCallStats(call, mappedRoomId);
                break;
            }
        }
    };

    private async logCallStats(call: MatrixCall, mappedRoomId: string): Promise<void> {
        const stats = await call.getCurrentCallStats();
        logger.debug(
            `Call completed. Call ID: ${call.callId}, virtual room ID: ${call.roomId}, ` +
            `user-facing room ID: ${mappedRoomId}, direction: ${call.direction}, ` +
            `our Party ID: ${call.ourPartyId}, hangup party: ${call.hangupParty}, ` +
            `hangup reason: ${call.hangupReason}`,
        });
        fakeCall.emit(CallEvent.AssertedIdentityChanged);

        await roomChangePromise;
        callHandler.removeAllListeners();

        // If everything's gone well, we should have seen only one room change
        // event and the call should now be in Charlie's room.
        // If it's not obeying any, the call will still be in NATIVE_ROOM_ALICE.
        // If it incorrectly obeyed both asserted identity changes, either it will
        // have just processed one and the call will be in the wrong room, or we'll
        // have seen two room change dispatches.
        expect(callRoomChangeEventCount).toEqual(1);
        expect(callHandler.getCallForRoom(NATIVE_ROOM_BOB)).toBeNull();
        expect(callHandler.getCallForRoom(NATIVE_ROOM_CHARLIE)).toBe(fakeCall);
    });
});

describe('LegacyCallHandler without third party protocols', () => {
    let dmRoomMap;
    let callHandler: LegacyCallHandler;
    let audioElement: HTMLAudioElement;
    let fakeCall;

    beforeEach(() => {
        stubClient();
        MatrixClientPeg.get().createCall = roomId => {
            if (fakeCall && fakeCall.roomId !== roomId) {
                throw new Error("Only one call is supported!");
            }
            fakeCall = new FakeCall(roomId);
            return fakeCall;
        };

        MatrixClientPeg.get().getThirdpartyProtocols = () => {
            throw new Error("Endpoint unsupported.");
        };

        callHandler = new LegacyCallHandler();
        callHandler.start();

        const nativeRoomAlice = mkStubDM(NATIVE_ROOM_ALICE, NATIVE_ALICE);

        MatrixClientPeg.get().getRoom = roomId => {
            switch (roomId) {
                case NATIVE_ROOM_ALICE:
                    return nativeRoomAlice;
            }
        };

        dmRoomMap = {
            getUserIdForRoomId: (roomId: string) => {
                if (roomId === NATIVE_ROOM_ALICE) {
                    return NATIVE_ALICE;
                } else {
                    return null;
                }
            },
            getDMRoomsForUserId: (userId: string) => {
                if (userId === NATIVE_ALICE) {
                    return [NATIVE_ROOM_ALICE];
                } else {
                    return [];
                }
            },
        };
        DMRoomMap.setShared(dmRoomMap);

        MatrixClientPeg.get().getThirdpartyUser = (_proto, _params) => {
            throw new Error("Endpoint unsupported.");
        };

        audioElement = document.createElement('audio');
        audioElement.id = "remoteAudio";
        document.body.appendChild(audioElement);
    });

    afterEach(() => {
        callHandler.stop();
        DMRoomMap.setShared(null);
        // @ts-ignore
        window.mxLegacyCallHandler = null;
        fakeCall = null;
        MatrixClientPeg.unset();

        document.body.removeChild(audioElement);
        SdkConfig.unset();
    });

    it('should still start a native call', async () => {
        callHandler.placeCall(NATIVE_ROOM_ALICE, CallType.Voice);

        await untilCallHandlerEvent(callHandler, LegacyCallHandlerEvent.CallState);

        // Check that a call was started: its room on the protocol level
        // should be the virtual room
        expect(fakeCall.roomId).toEqual(NATIVE_ROOM_ALICE);

        // but it should appear to the user to be in thw native room for Bob
        expect(callHandler.roomIdForCall(fakeCall)).toEqual(NATIVE_ROOM_ALICE);
    });

    describe('incoming calls', () => {
        const roomId = 'test-room-id';

        const mockAudioElement = {
            play: jest.fn(),
            pause: jest.fn(),
        } as unknown as HTMLMediaElement;
        beforeEach(() => {
            jest.clearAllMocks();
            jest.spyOn(SettingsStore, 'getValue').mockImplementation(setting =>
                setting === UIFeature.Voip);

            jest.spyOn(MatrixClientPeg.get(), 'supportsVoip').mockReturnValue(true);

            MatrixClientPeg.get().isFallbackICEServerAllowed = jest.fn();
            MatrixClientPeg.get().prepareToEncrypt = jest.fn();

            MatrixClientPeg.get().pushRules = {
                global: {
                    [PushRuleKind.Override]: [{
                        rule_id: RuleId.IncomingCall,
                        default: false,
                        enabled: true,
                        actions: [
                            {
                                set_tweak: TweakName.Sound,
                                value: 'ring',
                            },
                        ]
                        ,
                    }],
                },
            };

            jest.spyOn(document, 'getElementById').mockReturnValue(mockAudioElement);

            // silence local notifications by default
            jest.spyOn(MatrixClientPeg.get(), 'getAccountData').mockImplementation((eventType) => {
                if (eventType.includes(LOCAL_NOTIFICATION_SETTINGS_PREFIX.name)) {
                    return new MatrixEvent({
                        type: eventType,
                        content: {
                            is_silenced: true,
                        },
                    });
                }
            });
        });

        it('listens for incoming call events when voip is enabled', () => {
            const call = new MatrixCall({
                client: MatrixClientPeg.get(),
                roomId,
            });
            const cli = MatrixClientPeg.get();

            cli.emit(CallEventHandlerEvent.Incoming, call);

            // call added to call map
            expect(callHandler.getCallForRoom(roomId)).toEqual(call);
        });

        it('rings when incoming call state is ringing and notifications set to ring', () => {
            // remove local notification silencing mock for this test
            jest.spyOn(MatrixClientPeg.get(), 'getAccountData').mockReturnValue(undefined);
            const call = new MatrixCall({
                client: MatrixClientPeg.get(),
                roomId,
            });
            const cli = MatrixClientPeg.get();

            cli.emit(CallEventHandlerEvent.Incoming, call);

            // call added to call map
            expect(callHandler.getCallForRoom(roomId)).toEqual(call);
            call.emit(CallEvent.State, CallState.Ringing, CallState.Connected);

            // ringer audio element started
            expect(mockAudioElement.play).toHaveBeenCalled();
        });

        it('does not ring when incoming call state is ringing but local notifications are silenced', () => {
            const call = new MatrixCall({
                client: MatrixClientPeg.get(),
                roomId,
            });
            const cli = MatrixClientPeg.get();

            cli.emit(CallEventHandlerEvent.Incoming, call);

            // call added to call map
            expect(callHandler.getCallForRoom(roomId)).toEqual(call);
            call.emit(CallEvent.State, CallState.Ringing, CallState.Connected);

            // ringer audio element started
            expect(mockAudioElement.play).not.toHaveBeenCalled();
            expect(callHandler.isCallSilenced(call.callId)).toEqual(true);
        });

        it('should force calls to silent when local notifications are silenced', async () => {
            const call = new MatrixCall({
                client: MatrixClientPeg.get(),
                roomId,
            });
            const cli = MatrixClientPeg.get();

            cli.emit(CallEventHandlerEvent.Incoming, call);

            expect(callHandler.isForcedSilent()).toEqual(true);
            expect(callHandler.isCallSilenced(call.callId)).toEqual(true);
        });

        it('does not unsilence calls when local notifications are silenced', async () => {
            const call = new MatrixCall({
                client: MatrixClientPeg.get(),
                roomId,
            });
            const cli = MatrixClientPeg.get();
            const callHandlerEmitSpy = jest.spyOn(callHandler, 'emit');

            cli.emit(CallEventHandlerEvent.Incoming, call);
            // reset emit call count
            callHandlerEmitSpy.mockClear();

            callHandler.unSilenceCall(call.callId);
            expect(callHandlerEmitSpy).not.toHaveBeenCalled();
            // call still silenced
            expect(callHandler.isCallSilenced(call.callId)).toEqual(true);
            // ringer not played
            expect(mockAudioElement.play).not.toHaveBeenCalled();
        });
    });
});
